/* @lc app=leetcode id=3948 lang=kotlin */ class Solution { fun nxt(nums: IntArray, sm: IntArray, i: Int): Int = sm[i].let { M -> if (M == 0) i + 1 else HashSet<Int>().let { seen -> generateSequence(i) { it + 1 }.first { j -> (if (nums[j] < M) seen.add(nums[j]) else false).let { seen.size == M } } + 1 } } fun maximumMEX(nums: IntArray): IntArray = nums.size.let { n -> IntArray(n + 1).also { sm -> BooleanArray(n + 2).let { seen -> (n - 1 downTo 0).fold(0) { mex, i -> (if (nums[i] <= n) seen.set(nums[i], true) else Unit).let { generateSequence(mex) { it + 1 }.first { !seen[it] }.also { sm[i] = it } } } } }.let { sm -> generateSequence(0) { i -> nxt(nums, sm, i).takeIf { it < n } }.map { sm[it] }.toList().toIntArray() } } }